questionvariables.text:
non:rand_with_step(3,10,1);
irt:rand_with_prohib(6,10,[non]);
i_on:rand_with_prohib(6,15,[non,irt]);
r_on:rand_with_prohib(6,15,[non,irt,i_on]);
t_on:rand_with_prohib(6,15,[non,irt,i_on,r_on]);
ir_on:rand_with_prohib(6,15,[non,irt,i_on,r_on,t_on]);
it_on :rand_with_prohib(6,15,[non,irt,i_on,r_on,t_on,ir_on]);
rt_on:100-(non+irt+i_on+r_on+t_on+ir_on+it_on);
ir:ir_on+irt;
it:it_on+irt;
rt:rt_on+irt;
/*probabilities*/
iron:i_on+ir_on+it_on+irt;
r:r_on+ir_on+rt_on+irt;
t:t_on+it_on+rt_on+irt;

/*model answers*/
ta:r+iron+t-ir-rt-it+irt; /*should be the same as 1-non*/
ta1:float(ta/100);
